code_example:
#include <iostream>
class A { public: int a; };
class B : virtual public A { public: int b; };
class C : virtual public A { public: int c; };
class D : public B, public C { public: int d; };
int main() {
  D d;
  std::cout << &d.a << " \n"; // Address of A will not be directly embedded
  //Observe the address of a, and its difference from b and c to understand the layout
  std::cout << &d.b << " \n";
  std::cout << &d.c << " \n";
  std::cout << &d.d << " \n";
  return 0;
}
